<template>
  <div>
    <div
      v-if="loading"
      style="display: flex; align-items: center; justify-content: center"
    >
      <a-spin />
    </div>
    <div v-else class="markdown-body" v-html="renderedMarkdown"></div>
  </div>
</template>

<script setup>
// 1. 修正引入：从 "vue" 中引入 watch，而不是 less
import {  ref, watch } from "vue";
import { marked } from "marked";

// 建议改用 light 版本，这样就不会受系统深色模式影响自动变黑了
import "github-markdown-css/github-markdown-light.css";
import { useRoute } from "vue-router";
// 2. 删除错误的引入： import { watch } from "less"; (这行被删除了)

const props = defineProps({
  src: String, // 传入 markdown 文件路径
});

const route = useRoute();
const loading = ref(false);
const renderedMarkdown = ref("");

const loadMarkdown = async (src) => {
  loading.value = true;
  try {
    const res = await fetch(src);
    const mdText = await res.text();
    // 直接解析，不再使用 marked-highlight 插件
    renderedMarkdown.value = marked.parse(mdText);
  } catch (e) {
    console.error("加载 Markdown 文件失败:", e);
    renderedMarkdown.value = '<p style="color:red;">加载失败</p>';
  }
  loading.value = false;
};

// 如果你希望页面加载时自动解析，可以取消下面这行的注释
// onMounted(loadMarkdown(props.src)); 
// 注意：上面这行在 watch immediate: true 存在时通常不需要，或者会导致重复调用。
// watch 会在组件创建时立即执行一次。

watch(
  () => route.params,
  (newParams) => {
    // 确保有 id 才去拼接路径，否则使用默认 props.src
    // 注意：这里的逻辑假设路由变化时一定要重新加载。
    // 如果 props.src 是父组件传下来的，可能还需要监听 props.src 的变化。
    const targetSrc = newParams.id ? `/blog/markdown/${newParams.id}.md` : props.src;
    if (targetSrc) {
      loadMarkdown(targetSrc);
    }
  },
  { immediate: true }
);
</script>

<style scoped>
/* === 公共样式 (同时应用于手机和电脑) === */
.markdown-body {
  background: #fff;
  color: #222;
  border-radius: 10px;
  box-shadow: 1px 1px 1px rgba(0, 0, 0, 0.1);
  font-size: 1.1rem;
  line-height: 1.8;
  word-break: break-word;
  overflow-x: auto;
}

/* --- 核心修复：强制表格样式为亮色风格 --- */
.markdown-body table {
  display: block;
  width: 100%;
  overflow: auto;
  border-spacing: 0;
  border-collapse: collapse;
}

.markdown-body table tr {
  background-color: #fff !important; /* 强制背景白，覆盖深色模式 */
  border-top: 1px solid #c6cbd1;
}

/* 表格斑马纹（偶数行浅灰） */
.markdown-body table tr:nth-child(2n) {
  background-color: #f6f8fa !important;
}

.markdown-body table th,
.markdown-body table td {
  padding: 6px 13px;
  border: 1px solid #dfe2e5;
  color: #24292e; /* 强制文字黑 */
}
/* ------------------------------------- */

/* 删除了原本针对 atom-one-dark 主题的 pre 背景色设置 
   现在 pre 的样式将由 github-markdown-light.css 默认接管
   这里只保留一些基础的布局微调
*/
.markdown-body pre {
  border-radius: 8px;
  padding: 1.1rem 1rem;
  margin: 1.5em 0;
  font-size: 1em;
  /* 如果需要覆盖默认的浅灰色背景，可以在这里添加 background: #f6f8fa; */
}

.markdown-body code {
  /* 保留行内代码的小红字风格，如果不想要也可以删掉 */
  background: #f6f8fa;
  color: #d6336c;
  padding: 0.2em 0.4em;
  border-radius: 4px;
  font-size: 1em;
}

/* 让代码块内的 code 不继承行内 code 的背景和颜色，回归默认 */
.markdown-body pre code {
  background: transparent;
  color: inherit;
  padding: 0;
  border-radius: 0;
}

.markdown-body h1,
.markdown-body h2,
.markdown-body h3 {
  border-bottom: 1px solid #eaecef;
  padding-bottom: 0.3em;
  margin-bottom: 1em;
  font-weight: 700;
}

.markdown-body ul {
  padding-left: 2em;
}

.markdown-body blockquote {
  background: #f6f8fa;
  border-left: 4px solid #d1d5da;
  margin: 1em 0;
  padding: 1em;
  color: #6a737d;
}

.markdown-body img {
  max-width: 100%;
  border-radius: 6px;
}

/* === 响应式差异设置 === */
@media (min-width: 601px) {
  .markdown-body {
    padding: 2rem;
  }
}

@media (max-width: 600px) {
  .markdown-body {
    padding: 0.6rem;
  }
}
</style>